	<header class="certloom-workspace-card-head"><div><span class="certloom-eyebrow"><?php esc_html_e( 'Connected results', 'certloom' ); ?></span><h2 id="certloom-webhook-v2-title"><?php esc_html_e( 'App connections with results', 'certloom' ); ?></h2><p><?php esc_html_e( 'Let a trusted app confirm qualification and supply mapped results. Your customers complete their permitted details on your website; your Program supplies shared values.', 'certloom' ); ?></p></div><span class="certloom-count-chip"><?php echo esc_html( number_format_i18n( count( $app_connections ) ) ); ?></span></header>
	<div class="certloom-callout certloom-callout-info"><span class="dashicons dashicons-shield" aria-hidden="true"></span><div><strong><?php esc_html_e( 'Choose a Program, connect its results, then test', 'certloom' ); ?></strong><p><?php esc_html_e( 'Use exact Recipient External IDs and automatic numbering. Map only fields configured as app-owned results. Send a signed test first; it checks readiness without creating a request, issuing a certificate or sending email.', 'certloom' ); ?></p></div></div>
	<?php if ( ! empty( $app_data['one_time_secret'] ) ) : $app_secret = $app_data['one_time_secret']; ?>
	<div class="certloom-one-time-secret" role="status"><h3><?php esc_html_e( 'Copy your app signing secret now', 'certloom' ); ?></h3><p><?php esc_html_e( 'Keep this in the sending app. Certloom stores it encrypted and shows it once.', 'certloom' ); ?></p><div class="certloom-connection-value-grid"><label><span><?php esc_html_e( 'Endpoint', 'certloom' ); ?></span><input type="text" readonly value="<?php echo esc_attr( rest_url( 'certloom/v2/integrations/webhook/' . $app_secret['key'] ) ); ?>" onclick="this.select();"></label><label><span><?php esc_html_e( 'Signing secret', 'certloom' ); ?></span><input type="text" readonly value="<?php echo esc_attr( $app_secret['secret'] ); ?>" onclick="this.select();"></label></div></div>
	<?php endif; ?>
	<?php if ( ! empty( $app_data['error'] ) ) : ?><div class="notice notice-error inline"><p><?php echo esc_html( $app_data['error']->get_error_message() ); ?></p></div><?php endif; ?>
	<?php if ( $app_capable ) : ?>
	<details class="certloom-create-drawer" <?php echo $app_connections ? '' : 'open'; ?>><summary><span class="dashicons dashicons-plus-alt2" aria-hidden="true"></span><?php esc_html_e( 'Connect an app', 'certloom' ); ?></summary><div class="certloom-create-drawer-body">
		<form method="get" action="<?php echo esc_url( admin_url( 'admin.php' ) ); ?>" class="certloom-clean-form"><input type="hidden" name="page" value="certloom-integrations"><input type="hidden" name="v2_context" value="1"><div class="certloom-form-grid certloom-form-grid-3"><label class="certloom-field-control"><span><?php esc_html_e( '1. Choose your Program', 'certloom' ); ?></span><select name="program_id" required data-certloom-context-lookup="program" data-certloom-context-nonce="<?php echo esc_attr( $certloom_context_nonce ); ?>"><option value=""><?php esc_html_e( 'Choose a Program', 'certloom' ); ?></option><?php foreach ( $app_data['programs'] ?? array() as $program ) : ?><option value="<?php echo esc_attr( $program['id'] ); ?>" <?php selected( $app_data['program_id'] ?? 0, $program['id'] ); ?>><?php echo esc_html( $program['title'] ); ?></option><?php endforeach; ?></select></label><label class="certloom-field-control"><span><?php esc_html_e( 'Batch (optional)', 'certloom' ); ?></span><select name="batch_id" data-certloom-context-lookup="batch" data-certloom-context-nonce="<?php echo esc_attr( $certloom_context_nonce ); ?>"><option value="0"><?php esc_html_e( 'Use Program context', 'certloom' ); ?></option><?php if ( ! empty( $app_data['batch_id'] ) ) : ?><option value="<?php echo esc_attr( $app_data['batch_id'] ); ?>" selected><?php echo esc_html( sprintf( __( 'Selected Batch #%d', 'certloom' ), $app_data['batch_id'] ) ); ?></option><?php endif; ?></select></label></div><div class="certloom-form-actions"><button type="submit" class="button"><?php esc_html_e( 'Show this Program’s result fields', 'certloom' ); ?></button></div></form>
		<?php if ( ! empty( $app_data['context_ready'] ) ) : ?>
