		<h3><?php echo esc_html( sprintf( __( '2. Connect results for %s', 'certloom' ), $app_program_labels[ $app_data['program_id'] ] ?? __( 'this Program', 'certloom' ) ) ); ?></h3><label class="certloom-field-control"><span><?php esc_html_e( 'Connection name', 'certloom' ); ?></span><input name="name" required maxlength="120" placeholder="<?php esc_attr_e( 'e.g. Training portal results', 'certloom' ); ?>"></label>
		<p class="description"><?php esc_html_e( 'Enter the name your app sends for each result. For example, map its Score to your Assessment score field. Leave optional results blank if the app will not supply them.', 'certloom' ); ?></p>
		<div class="certloom-form-grid certloom-form-grid-2"><?php foreach ( $app_data['fields'] as $field ) : ?><label class="certloom-field-control"><span><?php echo esc_html( $field['label'] ); ?><?php if ( $field['required'] ) : ?> · <?php esc_html_e( 'Required', 'certloom' ); ?><?php endif; ?></span><input name="field_slots[<?php echo esc_attr( $field['key'] ); ?>]" maxlength="64" pattern="[A-Za-z][A-Za-z0-9_]{0,63}" <?php echo $field['required'] ? 'required' : ''; ?> placeholder="<?php echo esc_attr( $field['key'] ); ?>"><small><?php echo esc_html( sprintf( __( 'App-owned %1$s → %2$s', 'certloom' ), $field['type'], $field['key'] ) ); ?></small></label><?php endforeach; ?></div>
		<?php if ( ! $app_data['fields'] ) : ?><p><?php esc_html_e( 'This Program has no app-owned result fields. The connection can confirm qualification; configured customer details and shared values still use their own source.', 'certloom' ); ?></p><?php endif; ?>
		<div class="certloom-form-actions"><button type="submit" class="button button-primary"><?php esc_html_e( 'Create app connection', 'certloom' ); ?></button></div></form>
		<?php endif; ?>
	</div></details>
	<?php endif; ?>
	<?php foreach ( $app_connections as $connection ) : $app_key = $connection['key']; ?>
	<article class="certloom-mapping-row certloom-webhook-row"><div class="certloom-webhook-main"><strong><?php echo esc_html( $connection['name'] ); ?></strong><small><?php echo esc_html( $app_program_labels[ $connection['program_id'] ] ?? __( 'Program', 'certloom' ) ); ?></small><code><?php echo esc_html( rest_url( 'certloom/v2/integrations/webhook/' . $app_key ) ); ?></code></div><span class="certloom-state-pill <?php echo $connection['active'] ? 'is-success' : ''; ?>"><?php echo $connection['active'] ? esc_html__( 'On', 'certloom' ) : esc_html__( 'Paused', 'certloom' ); ?></span><div class="certloom-row-actions"><?php foreach ( array( 'rotate' => __( 'Rotate secret', 'certloom' ), 'delete' => __( 'Remove', 'certloom' ) ) as $action => $label ) : ?><form method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>" data-ecapla-confirm="<?php echo esc_attr( 'rotate' === $action ? __( 'Rotate this secret? Update the sending app before its next request.', 'certloom' ) : __( 'Remove this connection? New events stop; existing pending requests remain held for review.', 'certloom' ) ); ?>"><input type="hidden" name="action" value="certloom_webhook_v2_<?php echo esc_attr( $action ); ?>"><input type="hidden" name="source_key" value="<?php echo esc_attr( $app_key ); ?>"><input type="hidden" name="fingerprint" value="<?php echo esc_attr( $connection['fingerprint'] ); ?>"><?php wp_nonce_field( 'certloom_webhook_v2_' . $action . '_' . $app_key ); ?><button type="submit" class="button button-small"><?php echo esc_html( $label ); ?></button></form><?php endforeach; ?></div></article>
	<details class="certloom-technical-details"><summary><?php esc_html_e( 'Mapped results and connection status', 'certloom' ); ?></summary><form method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>" class="certloom-clean-form"><input type="hidden" name="action" value="certloom_webhook_v2_save"><input type="hidden" name="source_key" value="<?php echo esc_attr( $app_key ); ?>"><input type="hidden" name="fingerprint" value="<?php echo esc_attr( $connection['fingerprint'] ); ?>"><?php wp_nonce_field( 'certloom_webhook_v2_save_' . $app_key ); ?><p><?php esc_html_e( 'Changing a mapping or pausing it holds requests accepted under its previous revision. Review those requests before asking the app to send a new qualifying event. Rotating the signing secret keeps the result mapping.', 'certloom' ); ?></p><?php if ( $connection['field_error'] ) : ?><p class="description"><?php echo esc_html( $connection['field_error'] ); ?></p><?php endif; ?><p class="description"><?php esc_html_e( 'Map newly added app results here. Leave an optional result blank to remove its mapping. Every required result needs a mapping before you turn the connection on.', 'certloom' ); ?></p><div class="certloom-form-grid certloom-form-grid-2"><?php $app_slots = array_flip( $connection['fields'] ); foreach ( $connection['field_choices'] as $field ) : ?><label class="certloom-field-control"><span><?php echo esc_html( $field['label'] ); ?><?php if ( $field['required'] ) : ?> ? <?php esc_html_e( 'Required', 'certloom' ); ?><?php endif; ?></span><input name="field_slots[<?php echo esc_attr( $field['key'] ); ?>]" value="<?php echo esc_attr( $app_slots[ $field['key'] ] ?? '' ); ?>" maxlength="64" pattern="[A-Za-z][A-Za-z0-9_]{0,63}"><small><?php echo esc_html( ! empty( $field['unavailable'] ) ? __( 'No longer available in this Program. Clear this mapping or pause the connection.', 'certloom' ) : sprintf( __( 'App-owned %1$s ? %2$s', 'certloom' ), $field['type'], $field['key'] ) ); ?></small></label><?php endforeach; ?></div><label class="certloom-switch-row"><input type="checkbox" name="active" value="1" <?php checked( $connection['active'] ); ?>><span><?php esc_html_e( 'Accept new events', 'certloom' ); ?></span></label><div class="certloom-form-actions"><button type="submit" class="button"><?php esc_html_e( 'Save connection', 'certloom' ); ?></button></div></form></details>
	<?php endforeach; ?>
	<details class="certloom-technical-details"><summary><?php esc_html_e( 'Send a test, then a qualifying event', 'certloom' ); ?></summary><p><?php esc_html_e( 'Send the same version 2 payload to the endpoint plus /test first. A test receipt lists current blockers and changes nothing. Use the main endpoint for live intake. Evidence updates use /requests/{request_ref}/evidence and the current request revision. If an enrollment detail is needed, supply that recipient’s exact registration_id.', 'certloom' ); ?></p><p><?php esc_html_e( 'Sign UTF-8 bytes: certloom-webhook-v2, POST, the /certloom/v2 route, the Unix timestamp and the exact JSON body, separated by newline characters. Send X-Certloom-Timestamp and X-Certloom-Signature (sha256= followed by the HMAC-SHA256 hex digest). Each route needs its own signature; the five-minute timestamp window applies.', 'certloom' ); ?></p><p><?php esc_html_e( 'Payload fields: schema_version (2), event_id, recipient_external_id, registration_id (0 if unused), completed_at (UTC), and evidence containing eligibility, checked_at, valid_until and mapped fields. Each supplied result contains a text value and stable revision. Keep private customer details out of app result payloads.', 'certloom' ); ?></p></details>
</section>
